600	    /**
601	     * Compose an owner's canonical {@code address} from the two accepted input forms, preferring the
602	     * structured fields over the flat value. When a non-blank {@code addressLine1} is present the
603	     * result is that line, with a single space and {@code addressLine2} appended when the second line
604	     * is present; otherwise the flat {@code address} value is used. All three arguments are expected
605	     * to already be normalized (see {@link #normalizeAddress(String)}). This is the single source of
606	     * truth for how an owner's address is read, so every consumer (the stored value and the response)
607	     * sees the structured fields when present and the flat value as the backward-compatible fallback.
608	     *
609	     * @param addressLine1 the normalized first structured line, possibly {@code null} or blank
610	     * @param addressLine2 the normalized optional second structured line, possibly {@code null} or blank
611	     * @param flatAddress the normalized flat address, possibly {@code null}
612	     * @return the composed address, or the flat value / {@code null} when no structured line is present
613	     */
614	    public static String composeAddress(String addressLine1, String addressLine2, String flatAddress) {
615	        if (isPresent(addressLine1)) {
616	            if (isPresent(addressLine2)) {
617	                return addressLine1 + " " + addressLine2;
618	            }
619	            return addressLine1;
620	        }
621	        return flatAddress;
622	    }
