624	    /**
625	     * Whether an address field supplies a usable value, i.e. is non-{@code null} and not blank. This
626	     * is the shared "presence" rule behind both {@link #composeAddress(String, String, String)} and
627	     * {@link #hasAddress(String, String)}, so they agree on what counts as a supplied address field.
628	     *
629	     * @param value the address field, possibly {@code null}
630	     * @return {@code true} if the value is present and non-blank
631	     */
632	    private static boolean isPresent(String value) {
633	        return value != null && !value.isBlank();
634	    }
