636	    /**
637	     * Check whether an owner supplies a postal address in at least one accepted form: a non-blank
638	     * structured {@code addressLine1}, or a non-blank flat {@code address}. This is the single source
639	     * of truth for the address presence rule, shared by the DTO validation and any persistence path.
640	     *
641	     * @param addressLine1 the structured first line, possibly {@code null}
642	     * @param address the flat address, possibly {@code null}
643	     * @return {@code true} if either form supplies a non-blank value, {@code false} otherwise
644	     */
645	    public static boolean hasAddress(String addressLine1, String address) {
