665	    /**
666	     * Compute the stable identifier shared by all owners in the same household, i.e. with the same
667	     * last name (compared case-insensitively with collapsed whitespace, see
668	     * {@link #normalizeHousehold(String)}) and the same postcode. The value is deterministic in
669	     * those two fields, so two owners who share a last name and postcode are assigned the same id
670	     * automatically. It is formatted {@code 'HH-<HEX12>'} where {@code HEX12} is the first twelve
671	     * upper-cased hex characters of the SHA-256 digest of
672	     * {@code normalizedLastName + '|' + postcode}.
673	     *
674	     * @param lastName the owner's last name, possibly {@code null}
675	     * @param postcode the owner's postcode, possibly {@code null}
676	     * @return the household id, or {@code null} if either field is {@code null}
677	     */
678	    public static String householdId(String lastName, String postcode) {
679	        String normalizedLastName = normalizeHousehold(lastName);
680	        if (normalizedLastName == null || postcode == null) {
681	            return null;
682	        }
683	        String key = normalizedLastName + "|" + postcode;
684	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase();
685	    }
686	
687	    /**
688	     * Compute the full lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}. This is the
689	     * shared primitive behind every hash-derived owner value (the household id and the member id's
690	     * HASH8 segment), so they all agree on algorithm and encoding.
691	     *
692	     * @param value the string to digest, never {@code null}
693	     * @return the 64-character lower-case hex digest
694	     */
695	    private static String sha256Hex(String value) {
696	        try {
697	            byte[] digest = MessageDigest.getInstance("SHA-256")
698	                .digest(value.getBytes(StandardCharsets.UTF_8));
699	            StringBuilder hex = new StringBuilder(digest.length * 2);
700	            for (byte b : digest) {
701	                hex.append(String.format("%02x", b));
702	            }
703	            return hex.toString();
704	        } catch (NoSuchAlgorithmException e) {
705	            // SHA-256 is a standard algorithm required to be present on every JVM.
706	            throw new IllegalStateException("SHA-256 not available", e);
707	        }
708	    }
