710	    /**
711	     * Build an owner's {@code memberId}, the single unified owner identity assigned once when the owner
712	     * is created. It is formatted {@code '<REGION><FY><HASH8><CHK>'} (no separators) where:
713	     * <ul>
714	     *   <li>{@code REGION} is the region code derived from the postcode (see
715	     *       {@link #regionForPostcode(String)}), or {@code 'UNKNOWN'} when the postcode is absent or
716	     *       in no known range,</li>
717	     *   <li>{@code FY} is the two-digit fiscal year of the registration date (the last two digits of
718	     *       the fiscal-year number, see {@link #fiscalYearNumber(LocalDate)}),</li>
719	     *   <li>{@code HASH8} is the first eight upper-cased hex characters of the SHA-256 digest of the
720	     *       normalized telephone (see {@link #normalizeTelephone(String)}) concatenated with the last
721	     *       name (the same HASH8 used by the region-and-hash identity), and</li>
722	     *   <li>{@code CHK} is a single Luhn check digit (see {@link #luhn(String)}) over the digits of the
723	     *       {@code <REGION><FY><HASH8>} prefix.</li>
724	     * </ul>
725	     * The value is deterministic in the postcode, telephone, last name and registration date (e.g.
726	     * {@code 'NSW271A2B3C4D5'}); it carries no sequence number.
727	     *
728	     * @param postcode the owner's postcode, possibly {@code null}
729	     * @param telephone the owner's raw telephone, possibly {@code null}
730	     * @param lastName the owner's last name, possibly {@code null}
731	     * @param registrationDate the owner's registration date, possibly {@code null}
732	     * @return the member id, or {@code null} if the telephone, last name or registration date is
733	     *     {@code null}
734	     */
735	    public static String memberId(String postcode, String telephone, String lastName,
736	            LocalDate registrationDate) {
737	        if (telephone == null || lastName == null || registrationDate == null) {
738	            return null;
739	        }
740	        String region = regionForPostcode(postcode);
741	        if (region == null) {
742	            region = "UNKNOWN";
743	        }
744	        String fy = String.format("%02d", fiscalYearNumber(registrationDate) % 100);
745	        String normalizedTelephone = normalizeTelephone(telephone);
746	        String key = (normalizedTelephone == null ? "" : normalizedTelephone) + lastName;
747	        String hash8 = sha256Hex(key).substring(0, 8).toUpperCase();
748	        String prefix = region + fy + hash8;
749	        return prefix + luhn(prefix);
750	    }
