752	    /**
753	     * Extract the {@code REGION} segment of a {@code memberId}: the leading run of letters before the
754	     * two-digit {@code FY} segment (see {@link #memberId(String, String, String, LocalDate)}). Because
755	     * {@code REGION} is always alphabetic and is immediately followed by digits, the region is the
756	     * {@code memberId}'s leading letters. A {@code null} member id, or one with no leading letter,
757	     * yields {@code 'UNKNOWN'}.
758	     *
759	     * @param memberId the owner's member id, possibly {@code null}
760	     * @return the region segment, or {@code 'UNKNOWN'} when none can be read
761	     */
762	    public static String regionOf(String memberId) {
763	        if (memberId == null) {
764	            return "UNKNOWN";
765	        }
766	        int end = regionEnd(memberId);
767	        return end == 0 ? "UNKNOWN" : memberId.substring(0, end);
768	    }
