770	    /**
771	     * Locate the end of a {@code memberId}'s {@code REGION} segment: the index just past its leading
772	     * run of letters, which is where the two-digit {@code FY} segment begins (see
773	     * {@link #memberId(String, String, String, LocalDate)}). This is the single place the memberId's
774	     * region/FY boundary is read, shared by {@link #regionOf(String)} and {@link #fiscalYear(String)}.
775	     *
776	     * @param memberId the owner's member id, never {@code null}
777	     * @return the index after the leading letters (0 when the member id starts with a non-letter)
778	     */
779	    private static int regionEnd(String memberId) {
780	        int i = 0;
781	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
782	            i++;
783	        }
784	        return i;
785	    }
