787	    /**
788	     * Compute an owner's {@code identityKey}, the single derived value through which all
789	     * duplicate detection is now expressed. It is the lower-case hex SHA-256 digest (see
790	     * {@link #sha256Hex(String)}) of the three identity components joined with {@code '|'}:
791	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, where
792	     * <ul>
793	     *   <li>the normalized telephone (see {@link #normalizeTelephone(String)}),</li>
794	     *   <li>the lower-cased email (see {@link #normalizeEmail(String)}), or the empty string
795	     *       when no email is present, and</li>
796	     *   <li>the Soundex code of the last name (see {@link #soundex(String)}).</li>
797	     * </ul>
798	     * A {@code null} component is rendered as the empty string before hashing. Two owners are the
799	     * same identity only when their <em>whole</em> keys are equal; because the telephone is part of
800	     * the key, two members of the same household (same last name and postcode) with different
801	     * telephones have different keys and are not a hard duplicate.
802	     *
803	     * @param telephone the owner's raw telephone, possibly {@code null}
804	     * @param email the owner's email, possibly {@code null}
805	     * @param lastName the owner's last name, possibly {@code null}
806	     * @return the 64-character lower-case hex identity key, never {@code null}
807	     */
808	    public static String identityKey(String telephone, String email, String lastName) {
809	        String normalizedTelephone = normalizeTelephone(telephone);
810	        String normalizedEmail = normalizeEmail(email);
811	        String lastNameSoundex = soundex(lastName);
812	        String raw = (normalizedTelephone == null ? "" : normalizedTelephone)
813	            + "|" + (normalizedEmail == null ? "" : normalizedEmail)
814	            + "|" + (lastNameSoundex == null ? "" : lastNameSoundex);
815	        return sha256Hex(raw);
816	    }
