818	    /** Soundex digit for each consonant; vowels, {@code H}, {@code W} and {@code Y} map to '0'. */
819	    private static final Map<Character, Character> SOUNDEX_CODES = new HashMap<>();
820	    static {
821	        for (char c : "BFPV".toCharArray()) {
822	            SOUNDEX_CODES.put(c, '1');
823	        }
824	        for (char c : "CGJKQSXZ".toCharArray()) {
825	            SOUNDEX_CODES.put(c, '2');
826	        }
827	        for (char c : "DT".toCharArray()) {
828	            SOUNDEX_CODES.put(c, '3');
829	        }
830	        SOUNDEX_CODES.put('L', '4');
831	        for (char c : "MN".toCharArray()) {
832	            SOUNDEX_CODES.put(c, '5');
833	        }
834	        SOUNDEX_CODES.put('R', '6');
835	    }
836	
837	    /**
838	     * Compute the American Soundex code of a name: the upper-cased first letter followed by three
839	     * digits encoding the following consonants ({@code B,F,P,V}->1; {@code C,G,J,K,Q,S,X,Z}->2;
840	     * {@code D,T}->3; {@code L}->4; {@code M,N}->5; {@code R}->6), padded with zeros to length four.
841	     * Vowels ({@code A,E,I,O,U,Y}) separate codes; {@code H} and {@code W} are ignored so two
842	     * like-coded consonants on either side of them collapse to a single digit; adjacent letters with
843	     * the same code also collapse to one. Non-letters are stripped before coding. This is the single
844	     * source of truth for the surname component of the {@code identityKey} and the soft-match rule.
845	     *
846	     * @param name the raw name, possibly {@code null}
847	     * @return the four-character Soundex code, {@code null} if the input is {@code null}, or the empty
848	     *     string if the input contains no letters
849	     */
850	    public static String soundex(String name) {
851	        if (name == null) {
852	            return null;
853	        }
854	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
855	        if (letters.isEmpty()) {
856	            return "";
857	        }
858	        StringBuilder code = new StringBuilder();
859	        code.append(letters.charAt(0));
860	        char previous = SOUNDEX_CODES.getOrDefault(letters.charAt(0), '0');
861	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
862	            char c = letters.charAt(i);
863	            if (c == 'H' || c == 'W') {
864	                continue;
865	            }
866	            char digit = SOUNDEX_CODES.getOrDefault(c, '0');
867	            if (digit != '0' && digit != previous) {
868	                code.append(digit);
869	            }
870	            previous = digit;
871	        }
872	        while (code.length() < 4) {
873	            code.append('0');
874	        }
875	        return code.toString();
876	    }
