884	    /**
885	     * Resolve the fiscal-year number for a date, where the fiscal year starts on 1 July and is
886	     * named for the calendar year in which it ends. A date in July&ndash;December belongs to the
887	     * fiscal year of the next calendar year; a date in January&ndash;June belongs to the fiscal
888	     * year of its own calendar year.
889	     *
890	     * @param date the date to resolve, never {@code null}
891	     * @return the fiscal-year number (a four-digit calendar year)
892	     */
893	    private static int fiscalYearNumber(LocalDate date) {
894	        return date.getMonthValue() >= FISCAL_YEAR_START_MONTH ? date.getYear() + 1 : date.getYear();
895	    }
