897	    /**
898	     * Compute an owner's {@code fiscalYear}, the fiscal year of a date formatted {@code 'FY<YY>'}
899	     * where {@code YY} is the last two digits of the fiscal-year number (see
900	     * {@link #fiscalYearNumber(LocalDate)}). The fiscal year starts on 1 July, so a date of
901	     * {@code 2026-08-01} yields {@code 'FY27'} and {@code 2026-03-01} yields {@code 'FY26'}.
902	     *
903	     * @param date the date to derive the fiscal year from, possibly {@code null}
904	     * @return the fiscal year, or {@code null} if {@code date} is {@code null}
905	     */
906	    public static String fiscalYear(LocalDate date) {
907	        if (date == null) {
908	            return null;
909	        }
910	        return String.format("FY%02d", fiscalYearNumber(date) % 100);
911	    }
