913	    /**
914	     * Read an owner's {@code fiscalYear} from its {@code memberId}, formatted {@code 'FY<YY>'} where
915	     * {@code YY} is the two-digit {@code FY} segment carried by the member id (the two digits that
916	     * immediately follow the {@code REGION} segment, see
917	     * {@link #memberId(String, String, String, LocalDate)}). Reading it back from the member id keeps
918	     * the response's fiscal-year value consistent with the one encoded in the unified identifier.
919	     *
920	     * @param memberId the owner's member id, possibly {@code null}
921	     * @return the fiscal year formatted {@code 'FY<YY>'}, or {@code null} when no two-digit segment can
922	     *     be read from the member id
923	     */
924	    public static String fiscalYear(String memberId) {
925	        if (memberId == null) {
926	            return null;
927	        }
928	        int start = regionEnd(memberId);
929	        if (start + 2 > memberId.length()) {
930	            return null;
931	        }
932	        String yy = memberId.substring(start, start + 2);
933	        return yy.matches("\\d{2}") ? "FY" + yy : null;
934	    }
