936	    /**
937	     * Compute an owner's {@code membershipPoints}, the derived points score assigned on create. The
938	     * score starts at 0, gains 2 when an email is present, gains 1 when {@code namesakeCount} is 0,
939	     * gains 2 when the owner belongs to a household of 3 or more members (see {@code householdCount}),
940	     * and gains 3 when the owner's tenure is more than one fiscal year (the tenure being the number
941	     * of elapsed fiscal years from {@code registrationDate} to today, see
942	     * {@link #fiscalYear(LocalDate)}). Because a newly created owner has zero tenure, the tenure
943	     * points accrue only once the owner has been a member for more than a full fiscal year.
944	     *
945	     * @param namesakeCount the owner's namesake count, possibly {@code null}
946	     * @param email the owner's email, possibly {@code null}
947	     * @param householdCount the number of members in the owner's household, possibly {@code null}
948	     * @param registrationDate the owner's registration date, possibly {@code null}
949	     * @return the membership points, a non-negative integer
950	     */
951	    public static int membershipPoints(Integer namesakeCount, String email, Integer householdCount,
952	            LocalDate registrationDate) {
953	        int points = 0;
954	        if (email != null && !email.isEmpty()) {
955	            points += 2;
956	        }
957	        if (namesakeCount != null && namesakeCount == 0) {
958	            points += 1;
959	        }
960	        if (householdCount != null && householdCount >= 3) {
961	            points += 2;
962	        }
963	        if (registrationDate != null
964	            && fiscalYearNumber(LocalDate.now()) - fiscalYearNumber(registrationDate) > 1) {
965	            points += 3;
966	        }
967	        return points;
968	    }
