970	    /**
971	     * Map an owner's {@code membershipPoints} to its {@code membershipLevel}: level 1 for 0-1 points,
972	     * level 2 for 2-3, level 3 for 4-5 and level 4 for 6 or more.
973	     *
974	     * @param membershipPoints the owner's membership points
975	     * @return the membership level, an integer from 1 to 4
976	     */
977	    public static int membershipLevel(int membershipPoints) {
978	        if (membershipPoints >= 6) {
979	            return 4;
980	        }
981	        if (membershipPoints >= 4) {
982	            return 3;
983	        }
984	        if (membershipPoints >= 2) {
985	            return 2;
986	        }
987	        return 1;
988	    }
989	
990	    /**
991	     * Resolve this owner's effective {@code membershipLevel}: the capped value stored on the owner
992	     * when present (the create-time level after the household ceiling has been applied, see
993	     * {@link #getMembershipLevel()}), otherwise the level recomputed from the owner's membership
994	     * points (see {@link #membershipLevel(int)} and
995	     * {@link #membershipPoints(Integer, String, Integer, LocalDate)}). This is the single source of
996	     * truth for how a stored level is read back, deferred to by both the create-time household-ceiling
997	     * computation and the read-side DTO mapping so they always agree.
998	     *
999	     * @return the stored capped level when present, otherwise the level derived from membership points
1000	     */
1001	    public int effectiveMembershipLevel() {
1002	        if (this.membershipLevel != null) {
1003	            return this.membershipLevel;
1004	        }
1005	        return membershipLevel(membershipPoints(this.namesakeCount, this.email,
1006	            this.householdCount, this.registrationDate));
1007	    }
1008	
1009	    /**
1010	     * Fixed city-to-region table used by {@link #regionForCity(String)} to resolve a city's region
1011	     * for postcode validation, keyed by the exact city name.
1012	     */
1013	    private static final Map<String, String> CITY_REGION = Map.of(
1014	        "Sydney", "NSW",
1015	        "Melbourne", "VIC",
1016	        "Brisbane", "QLD");
1017	
1018	    /**
1019	     * Derive an owner's {@code locality}, the canonical region for the owner, from the {@code REGION}
1020	     * segment of the owner's {@code memberId} (see {@link #regionOf(String)}). Because the member id's
1021	     * region is itself derived from the postcode, the locality shares the owner's region-and-hash
1022	     * identity: it is the member id's leading region segment. When the owner has no member id the
1023	     * locality is {@code 'UNKNOWN'}.
1024	     *
1025	     * @param memberId the owner's member id, possibly {@code null}
1026	     * @return the canonical region string, or {@code 'UNKNOWN'} when no member id is present
1027	     */
1028	    public static String locality(String memberId) {
1029	        return regionOf(memberId);
1030	    }
1031	
1032	    /**
1033	     * Fixed region-to-timezone table used by {@link #timezone(String)} to resolve an owner's IANA
1034	     * timezone name from its canonical region ({@code NSW}->{@code Australia/Sydney},
1035	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). A region
1036	     * not in this table (including {@code 'UNKNOWN'}) has no timezone.
1037	     */
1038	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
1039	        "NSW", "Australia/Sydney",
1040	        "VIC", "Australia/Melbourne",
1041	        "QLD", "Australia/Brisbane");
1042	
1043	    /**
1044	     * Derive an owner's {@code timezone}, the IANA timezone name for the owner's locality/region,
1045	     * from the fixed {@link #REGION_TIMEZONE} table ({@code NSW}->{@code Australia/Sydney},
1046	     * {@code VIC}->{@code Australia/Melbourne}, {@code QLD}->{@code Australia/Brisbane}). The region
1047	     * is the owner's {@code locality} (see {@link #locality(String)}), itself the {@code REGION}
1048	     * segment of the member id. A region not in the table (including {@code 'UNKNOWN'}) has no
1049	     * timezone and yields {@code null}.
1050	     *
1051	     * @param memberId the owner's member id, possibly {@code null}
1052	     * @return the IANA timezone name, or {@code null} when the owner's region has no mapped timezone
1053	     */
1054	    public static String timezone(String memberId) {
1055	        return REGION_TIMEZONE.get(locality(memberId));
1056	    }
1057	
1058	    /**
1059	     * The canonical regions treated as {@code METRO} by {@link #ownerSegment()}: a locality is a
1060	     * known region exactly when it is {@code NSW}, {@code VIC} or {@code QLD}. Any other locality
1061	     * (including {@code 'UNKNOWN'}) is {@code REGIONAL}.
1062	     */
1063	    private static final Set<String> KNOWN_REGIONS = Set.of("NSW", "VIC", "QLD");
1064	
1065	    /**
1066	     * Derive this owner's {@code ownerSegment}, the marketing segment formatted
1067	     * {@code '<TIER>_<AREA>'}. {@code TIER} is {@code 'PREMIUM'} when the owner's effective
1068	     * membership level (see {@link #effectiveMembershipLevel()}) is 3 or more, otherwise
1069	     * {@code 'STANDARD'}. {@code AREA} is {@code 'METRO'} when the owner's locality (see
1070	     * {@link #locality(String)}) is a known region ({@code NSW}, {@code VIC} or {@code QLD}),
1071	     * otherwise {@code 'REGIONAL'}. The result is one of {@code 'PREMIUM_METRO'},
1072	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}.
1073	     *
1074	     * @return the owner's {@code '<TIER>_<AREA>'} segment
1075	     */
1076	    public String ownerSegment() {
1077	        String tier = effectiveMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
1078	        String area = KNOWN_REGIONS.contains(locality(this.memberId)) ? "METRO" : "REGIONAL";
1079	        return tier + "_" + area;
1080	    }
1081	
1082	    /**
1083	     * Resolve the canonical region for a city from the fixed {@link #CITY_REGION} table. A city not
1084	     * in the table (including {@code null}) resolves to {@code 'UNKNOWN'}.
1085	     *
1086	     * @param city the owner's city, possibly {@code null}
1087	     * @return the matching region, or {@code 'UNKNOWN'} when the city is not in the table
1088	     */
1089	    private static String regionForCity(String city) {
1090	        if (city == null) {
1091	            return "UNKNOWN";
1092	        }
1093	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
1094	    }
1095	
1096	    /**
1097	     * Fixed region-to-postcode-range table used by {@link #isPostcodeValidForCity(String, String)}
1098	     * and {@link #regionForPostcode(String)}, keyed by the canonical region. Each entry is the
1099	     * inclusive low and high bound of the region's valid 4-digit postcodes
1100	     * ({@code NSW} 2000-2099, {@code VIC} 3000-3099, {@code QLD} 4000-4099). A region not in this
1101	     * table (including {@code 'UNKNOWN'}) places no range constraint.
1102	     */
1103	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
1104	        "NSW", new int[] {2000, 2099},
1105	        "VIC", new int[] {3000, 3099},
1106	        "QLD", new int[] {4000, 4099});
1107	
1108	    /**
1109	     * Resolve the canonical region whose postcode range contains the given postcode, using the fixed
1110	     * {@link #REGION_POSTCODE_RANGES} table. A {@code null} postcode, one that is not exactly four
1111	     * digits, or one that falls in no known range resolves to {@code null}.
1112	     *
1113	     * @param postcode the owner's postcode, possibly {@code null}
1114	     * @return the matching region, or {@code null} when no range contains the postcode
1115	     */
1116	    private static String regionForPostcode(String postcode) {
1117	        if (postcode == null || !postcode.matches("\\d{4}")) {
1118	            return null;
1119	        }
1120	        int value = Integer.parseInt(postcode);
1121	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
1122	            int[] range = entry.getValue();
1123	            if (value >= range[0] && value <= range[1]) {
1124	                return entry.getKey();
1125	            }
1126	        }
1127	        return null;
1128	    }
1129	
1130	    /**
1131	     * Check whether a postcode is valid for an owner's city. Postcode is optional, so a
1132	     * {@code null} or empty postcode is always valid. When present it must be exactly four
1133	     * digits, and when the city's region (from the fixed city-to-region table) has a known postcode
1134	     * range the value must fall within that inclusive range. A city with no known region accepts
1135	     * any four-digit postcode. This is the single source of
1136	     * truth for postcode validity, shared by the DTO validation and any persistence path.
1137	     *
1138	     * @param postcode the owner's postcode, possibly {@code null}
1139	     * @param city the owner's city, possibly {@code null}
1140	     * @return {@code true} if the postcode is absent or valid for the city, {@code false} otherwise
1141	     */
1142	    public static boolean isPostcodeValidForCity(String postcode, String city) {
1143	        if (postcode == null || postcode.isEmpty()) {
1144	            return true;
1145	        }
1146	        if (!postcode.matches("\\d{4}")) {
1147	            return false;
1148	        }
1149	        int[] range = REGION_POSTCODE_RANGES.get(regionForCity(city));
1150	        if (range == null) {
1151	            return true;
1152	        }
1153	        int value = Integer.parseInt(postcode);
1154	        return value >= range[0] && value <= range[1];
1155	    }
1156	
1157	    /**
1158	     * Compute a single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
1159	     * characters are ignored. This is the standard Luhn check digit: each digit is weighted
1160	     * right-to-left, every second digit (starting with the rightmost) is doubled with digit sums above
1161	     * nine reduced by nine, and the check digit is the amount that brings the weighted sum up to the
1162	     * next multiple of ten. It is the shared primitive behind the {@code CHK} segment of the
1163	     * {@code memberId} (see {@link #memberId(String, String, String, LocalDate)}).
1164	     *
1165	     * @param value the string whose digits are summed, never {@code null}
1166	     * @return the Luhn check digit from 0 to 9
1167	     */
1168	    private static int luhn(String value) {
1169	        int sum = 0;
1170	        boolean dbl = true;
1171	        for (int i = value.length() - 1; i >= 0; i--) {
1172	            char c = value.charAt(i);
1173	            if (c < '0' || c > '9') {
1174	                continue;
1175	            }
1176	            int d = c - '0';
1177	            if (dbl) {
1178	                d *= 2;
1179	                if (d > 9) {
1180	                    d -= 9;
1181	                }
1182	            }
1183	            sum += d;
1184	            dbl = !dbl;
1185	        }
1186	        return (10 - (sum % 10)) % 10;
1187	    }
1188	
1189	    /**
1190	     * Derive an owner's {@code contactPreference}, the preferred channel for contacting the owner.
1191	     * The value is {@code 'EMAIL'} when an email is present and {@code 'PHONE'} otherwise. The value
1192	     * is deterministic in the email.
1193	     *
1194	     * @param email the owner's email, possibly {@code null}
1195	     * @return {@code 'EMAIL'} when an email is present, otherwise {@code 'PHONE'}
1196	     */
1197	    public static String contactPreference(String email) {
1198	        return (email != null && !email.isEmpty()) ? "EMAIL" : "PHONE";
1199	    }
1200	
1201	    /**
1202	     * Compose an owner's {@code salutation} from the optional honorific title and the last name.
1203	     * When a title is present the result is the title and the last name separated by a single space
1204	     * (e.g. {@code 'DR Franklin'}); when no title is given the result is just the last name. The
1205	     * value is deterministic in those two fields.
1206	     *
1207	     * @param title the owner's honorific title, possibly {@code null} or blank
1208	     * @param lastName the owner's last name, possibly {@code null}
1209	     * @return the composed salutation
1210	     */
1211	    public static String salutation(String title, String lastName) {
1212	        if (title == null || title.isBlank()) {
1213	            return lastName;
1214	        }
1215	        return title + " " + lastName;
1216	    }
1217	
1218	    /**
1219	     * Derive an owner's {@code ageBand}, the band the owner's age falls into on the registration
1220	     * date. The age in whole years is the number of completed years between {@code birthDate} and
1221	     * {@code registrationDate}, and the band is {@code 'MINOR'} when under 18, {@code 'ADULT'} when
1222	     * 18 to 64 inclusive, and {@code 'SENIOR'} when 65 or older. The value is deterministic in those
1223	     * two fields and is only defined when both are present.
1224	     *
1225	     * @param birthDate the owner's date of birth, possibly {@code null}
1226	     * @param registrationDate the owner's registration date, possibly {@code null}
1227	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when either date
1228	     *     is {@code null}
1229	     */
1230	    public static String ageBand(LocalDate birthDate, LocalDate registrationDate) {
1231	        if (birthDate == null || registrationDate == null) {
1232	            return null;
1233	        }
1234	        int age = Period.between(birthDate, registrationDate).getYears();
1235	        if (age < 18) {
1236	            return "MINOR";
1237	        }
1238	        if (age < 65) {
1239	            return "ADULT";
1240	        }
1241	        return "SENIOR";
1242	    }
1243	
1244	    protected Set<Pet> getPetsInternal() {
1245	        if (this.pets == null) {
1246	            this.pets = new HashSet<>();
1247	        }
1248	        return this.pets;
