1256	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
1257	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
1258	        return Collections.unmodifiableList(sortedPets);
