1280	    /**
1281	     * Return the Pet with the given name, or null if none found for this Owner.
1282	     *
1283	     * @param name to test
1284	     * @return true if pet name is already in use
1285	     */
1286	    public Pet getPet(String name, boolean ignoreNew) {
1287	        name = name.toLowerCase();
1288	        for (Pet pet : getPetsInternal()) {
1289	            if (!ignoreNew || !pet.isNew()) {
1290	                String compName = pet.getName();
1291	                compName = compName.toLowerCase();
1292	                if (compName.equals(name)) {
